-- Rewrite non-WSQ (C*) certification-exam-prep course details to official
-- exam domains + weights (source: vendor exam blueprints). 116 courses.
-- Only updates the description (course details). WSQ TGS- and partner M* SKUs
-- are untouched (SELECT by C-SKU matches nothing on partner DBs => no-op).
-- Idempotent (ON DUPLICATE KEY UPDATE). Pure ASCII. No content line ends in a semicolon before the terminating one.

SET @ad := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id=4 AND attribute_code='description');

